INSERT INTO public.personas
  (id, name, description, target_type, sector, company_size, target_role,
   maturity_level, main_problems, objectives, frequent_objections,
   recommended_approach, coach_notes, created_by, created_at, updated_at)
VALUES
  ('a401e721-a3c6-4749-8a0f-9ff064cb7ea3', 'RH', 'Le responsable RH cherche à maintenir des équipes performantes, engagées et stables dans un contexte de forte pression opérationnelle. Il constate que les commerciaux et équipes ADV sont souvent surchargés, stressés et démotivés par des tâches répétitives et administratives. Son objectif est d''améliorer les conditions de travail, limiter le turnover et soutenir la performance sans multiplier les recrutements.', 'PME', 'Industrie', '51-200', 'RH', NULL, 'Les commerciaux et équipes ADV sont en surcharge permanente.
Les tâches répétitives créent de la fatigue mentale et de la démotivation.
Le turnover augmente dans les fonctions commerciales et administratives.
Les équipes ressentent une pression constante liée aux objectifs et aux urgences.
Les collaborateurs passent trop de temps sur des tâches peu valorisantes.
Les recrutements sont difficiles et coûteux dans les fonctions support et commerciales.
Les managers signalent une baisse d''engagement des équipes.
Les risques de burn-out augmentent dans les périodes de forte activité.
Les équipes ont le sentiment de subir leur quotidien opérationnel.
Le manque de ressources crée des tensions internes entre services.', NULL, 'L''externalisation peut inquiéter les équipes.
Je ne veux pas que cela soit perçu comme un remplacement humain.
Le changement organisationnel peut créer des résistances.
Les collaborateurs peuvent craindre pour leur poste.
Comment intégrer un prestataire dans la culture d''entreprise ?
Nous devons préserver la cohésion interne.
Les équipes commerciales sont déjà réticentes au changement.
Il faut éviter d''ajouter de la complexité au quotidien.
L''onboarding d''un partenaire externe peut prendre du temps.
Je veux m''assurer que cela améliore réellement la qualité de vie au travail.
Le management doit rester humain et proche des équipes.
Comment éviter une déshumanisation des échanges clients ?
Les managers doivent adhérer au projet.
Nous devons sécuriser les données collaborateurs et clients.
Je veux des résultats concrets sur l''engagement et la charge de travail.', 'L''approche consiste à montrer aux RH que la surcharge administrative et les urgences permanentes épuisent progressivement les équipes commerciales et ADV. Salesback permet de soulager les collaborateurs, réduire la pression opérationnelle et améliorer l''engagement sans recruter massivement. L''objectif est de créer une organisation plus saine, plus stable et plus performante humainement comme économiquement.', NULL, '81ab69be-7fbd-4a7a-8d18-ed108c452d1c', '2026-05-26 12:25:58.23121+00', '2026-05-26 12:25:58.23121+00'),
  ('fd4e2093-52da-44b0-92f8-8a94adabfd59', 'CEO', 'CEO / Dirigeant PME/ETI à monté sa boite pour vendre, pas pour gérer des factures. L''ADV, ça tourne plus ou moins, mais au fond il sait que c''est bricolé. Recruter un profil dédié ? Trop long, trop risqué. Alors ça reste sur le bureau de quelqu''un qui a déjà autre chose à faire.', 'PME', 'Industrie', '11-50', 'CEO', NULL, 'CEO / Dirigeant PME ,perd de l''argent sans le voir vraiment pas sur l''ADV, mais sur les ventes que ses commerciaux ne font pas faute de temps. Il sait que son organisation ADV tient à une ou deux personnes, et que le jour où l''une d''elles part, c''est le chaos. Il veut scaler, mais pas recruter un CDI tous les six mois pour suivre la charge.', NULL, NULL, 'CEO / Dirigeant PME ,l''angle c''est le coût caché. Pas l''ADV en elle-même, mais ce que ça coûte de ne pas la structurer. On ne lui parle pas de process, on lui parle de temps de vente perdu et de risque RH qu''il porte sans s''en rendre compte. Le chiffre qui accroche : Salesback légèrement moins cher qu''un CDI , et sans trois mois de recrutement et 34% de turnover annuel dans la balance.', NULL, '81ab69be-7fbd-4a7a-8d18-ed108c452d1c', '2026-05-24 12:04:27.300522+00', '2026-05-24 12:04:27.300522+00'),
  ('b62f8ca8-67e3-4c19-a1ae-8f9b8b712b29', 'Directeur commercial ou Head of Sales', 'Le directeur commercial pilote une équipe sous pression permanente de résultats, mais constate que ses commerciaux passent une part énorme de leur temps sur des tâches administratives et des relances à faible valeur. Il cherche un moyen concret d''augmenter immédiatement la productivité commerciale sans recruter davantage ni complexifier l''organisation. Son objectif est simple : libérer du temps de vente réel pour transformer une équipe débordée en machine commerciale plus rentable et performante.', 'Autre', 'Industrie', '51-200', 'Directeur commercial ou Head of Sales', NULL, 'Ses commerciaux passent trop de temps sur l''administratif au lieu de vendre.
Les relances clients et le suivi ADV ralentissent fortement la performance commerciale.
Le CRM est mal tenu car les équipes manquent de temps et d''énergie.
Les commerciaux perdent en motivation à cause des tâches répétitives et peu valorisantes.
Le coût salarial des commerciaux est mal optimisé sur des missions à faible valeur ajoutée.
Les opportunités commerciales se refroidissent faute de suivi rapide et structuré.
Le directeur commercial manque de visibilité fiable sur l''activité réelle de son équipe.
Les équipes sont constamment dans l''urgence opérationnelle plutôt que dans la prospection stratégique.
La croissance commerciale est freinée par des blocages internes et organisationnels.
Recruter plus de commerciaux n''améliore pas forcément la productivité globale car le problème structurel reste présent.', NULL, 'Mes commerciaux doivent garder la relation client de A à Z.
-> Peur de perdre la proximité et la qualité relationnelle avec les clients.
Externaliser l''ADV risque de créer des erreurs ou des incompréhensions.
-> Crainte d''une baisse de qualité opérationnelle.
On a déjà essayé de déléguer, ça n''a pas marché.
-> Méfiance liée à de mauvaises expériences passées.
Mes équipes sont déjà organisées comme ça depuis des années.
-> Résistance au changement interne.
Je ne veux pas ajouter un prestataire de plus à gérer.
-> Peur d''ajouter de la complexité managériale.
Le vrai problème n''est pas l''ADV mais le manque de performance commerciale.
-> Il pense que le problème vient des commerciaux eux-mêmes.
Externaliser coûte cher.
-> Réflexe immédiat de comparaison coût vs salaire interne.
Mes commerciaux doivent rester polyvalents.
-> Croyance qu''un bon commercial doit tout gérer.
Le transfert d''informations risque d''être compliqué.
-> Crainte opérationnelle sur les process et outils.
Je ne suis pas sûr que ça fasse vraiment gagner 30% du temps.
-> Scepticisme sur la promesse de gain réel.
Nos process sont trop spécifiques pour être externalisés.
-> Impression que son entreprise est un cas particulier.
Les clients pourraient mal percevoir l''externalisation.
-> Peur d''une dégradation de l''image de marque.
Je préfère recruter en interne.
-> Besoin de contrôle et de maîtrise des ressources.
Le onboarding d''un prestataire va prendre trop de temps.
-> Projection d''une charge mentale supplémentaire à court terme.
Comment garantir la confidentialité des données clients ?
-> Inquiétude sur la sécurité et la conformité.', 'L''angle principal consiste à montrer que les commerciaux perdent une quantité énorme de temps et d''énergie sur des tâches administratives qui les empêchent de vendre pleinement. Salesback permet au directeur commercial de récupérer jusqu''à 30% de temps commercial utile sans recruter davantage, tout en améliorant la réactivité et la performance de l''équipe. L''idée est de transformer une organisation commerciale saturée par l''opérationnel en une équipe focalisée sur la vente, la croissance et le chiffre d''affaires.', NULL, '81ab69be-7fbd-4a7a-8d18-ed108c452d1c', '2026-05-26 12:25:39.310721+00', '2026-05-26 12:25:39.310721+00'),
  ('f739df63-4501-4a31-8121-8e76326f1d6d', 'Responsable ADV', 'Le responsable ADV est au cœur de la fluidité commerciale et opérationnelle de l''entreprise, mais il travaille constamment sous pression entre urgences clients, relances et surcharge administrative. Il doit garantir un suivi irréprochable tout en gérant des équipes débordées et des process souvent désorganisés. Son objectif est de maintenir un service client fluide, réduire les retards et éviter que l''ADV devienne un frein à la performance commerciale.', 'PME', 'Industrie', '11-50', 'Responsable ADV', NULL, 'Son équipe ADV est surchargée par les tâches répétitives et les urgences permanentes.
Les relances clients prennent énormément de temps au quotidien.
Les commerciaux transmettent souvent des dossiers incomplets ou imprécis.
Les erreurs administratives créent des tensions internes et externes.
Les délais de traitement ralentissent le cycle commercial.
L''équipe travaille constamment dans l''urgence et subit une forte pression.
Le manque de ressources empêche de structurer correctement les process.
Les clients relancent fréquemment pour obtenir des informations ou des mises à jour.
Les outils et CRM sont mal renseignés ou peu harmonisés.
Le responsable ADV manque de temps pour améliorer l''organisation et optimiser les flux.', NULL, 'Un prestataire externe ne connaîtra pas nos process.
Notre ADV est trop spécifique pour être externalisé.
J''ai peur de perdre le contrôle opérationnel.
L''intégration d''un partenaire externe va être compliquée.
Les commerciaux risquent de mal collaborer avec une équipe externe.
Nous avons déjà des outils en place.
La qualité de suivi client pourrait baisser.
Le transfert d''informations peut créer des erreurs.
Externaliser coûte plus cher que gérer en interne.
Mon équipe pourrait voir ça comme une menace.
Nous avons besoin de quelqu''un immédiatement opérationnel.
Nos clients sont exigeants, nous ne pouvons pas nous permettre d''erreurs.
Je ne veux pas passer mon temps à former un prestataire.
La confidentialité des données est critique.
Je ne suis pas sûr que cela réduise réellement la charge.', 'L''approche consiste à montrer au responsable ADV que son équipe est étouffée par les urgences, les relances et les tâches répétitives qui ralentissent toute l''organisation commerciale. Salesback agit comme un renfort opérationnel capable d''absorber une partie de la charge tout en améliorant la fluidité, la réactivité et la qualité de suivi client. L''objectif est de transformer un ADV sous tension permanente en une structure plus sereine, plus organisée et capable de soutenir la croissance de l''entreprise.', NULL, '81ab69be-7fbd-4a7a-8d18-ed108c452d1c', '2026-05-26 12:25:48.434619+00', '2026-05-26 12:25:48.434619+00'),
  ('231562d0-3dfa-46d7-8ee8-6e191e37b370', 'DAF', 'Le DAF cherche en permanence à améliorer la rentabilité de l''entreprise tout en maîtrisant les coûts et les risques opérationnels. Il constate que les équipes commerciales réalisent encore beaucoup de tâches administratives coûteuses et peu optimisées. Son objectif est d''augmenter l''efficacité globale de l''organisation sans recruter davantage ni alourdir la structure interne.', 'PME', 'Industrie', '51-200', 'DAF', NULL, 'Les commerciaux passent trop de temps sur des tâches administratives à faible valeur ajoutée.
Les coûts salariaux ne sont pas optimisés par rapport à la productivité réelle.
Les process ADV manquent d''efficacité et génèrent des pertes de temps importantes.
Les retards de suivi client ralentissent le cycle de vente et la facturation.
L''entreprise manque de visibilité sur le coût réel des tâches administratives commerciales.
Les équipes sont saturées mais les recrutements augmenteraient fortement les charges fixes.
La croissance de l''activité crée des tensions opérationnelles difficiles à absorber.
Les erreurs administratives génèrent des coûts cachés et des frictions internes.
Les commerciaux sont utilisés sur des missions qui ne maximisent pas leur ROI.
Les équipes support deviennent un goulot d''étranglement pour la croissance commerciale.', NULL, 'Pourquoi externaliser plutôt que recruter en interne ?
Quel est le ROI réel de votre solution ?
Externaliser peut créer une dépendance opérationnelle.
Comment garantir la confidentialité des données financières et clients ?
Nous avons déjà des process internes.
Le coût du prestataire doit être inférieur à une solution interne.
J''ai besoin d''indicateurs précis avant de prendre une décision.
L''intégration opérationnelle risque de perturber les équipes.
Je veux éviter les coûts cachés ou les prestations floues.
Notre organisation est spécifique et complexe.
Comment mesurer concrètement les gains de productivité ?
Les commerciaux doivent rester responsables de leurs dossiers.
Nous avons déjà investi dans des outils d''automatisation.
Je ne veux pas multiplier les prestataires externes.
Le changement organisationnel peut créer des résistances internes.', 'L''approche consiste à montrer au DAF que l''entreprise perd de la rentabilité lorsque des commerciaux coûteux consacrent une grande partie de leur temps à l''administratif et aux relances. Salesback permet d''optimiser les ressources existantes, améliorer la productivité commerciale et soutenir la croissance sans augmenter fortement les charges fixes. L''objectif est de transformer une organisation coûteuse et saturée en une structure plus rentable, plus flexible et plus performante financièrement.', NULL, '81ab69be-7fbd-4a7a-8d18-ed108c452d1c', '2026-05-26 12:25:53.19463+00', '2026-05-26 12:25:53.19463+00')
ON CONFLICT (id) DO NOTHING;

